/// Build the full program: prelude, optional TS strip of the user code, the
/// caller-supplied `input`, and the async entrypoint that always exits via
/// `std.exit` (returning from `_start` traps the vendored interpreter during
/// libc teardown; exiting first sidesteps it).
pub fn build_program(user_code: &str, input_json: &str, is_ts: bool) -> String {
    build_program_with("", user_code, input_json, is_ts)
}

/// [`build_program`], with extra prelude JavaScript injected between the
/// standard [`PRELUDE`] and the user code. The extra source runs with
/// `ferrite`/`console`/`fetch`/`env` already installed, so a consumer can add
/// its own globals (or wrap the existing ones) without forking the engine.
/// An empty `prelude_extra` produces byte-identical output to
/// [`build_program`].
pub fn build_program_with(
    prelude_extra: &str,
    user_code: &str,
    input_json: &str,
    is_ts: bool,
) -> String {
    let extra = if prelude_extra.is_empty() {
        String::new()
    } else {
        format!("{prelude_extra}\n")
    };
    let user = if is_ts {
        format!(
            "{TS_STRIP}\nconst __user_src = {src};\nconst __js = globalThis.__stripTypes(__user_src);\n",
            src = json_string(user_code)
        )
    } else {
        format!("const __js = {src};\n", src = json_string(user_code))
    };
    format!(
        "{PRELUDE}\n{extra}{user}globalThis.input = {input_json};\n\
         const __run = new Function('input', 'ferrite', 'console', 'fetch', 'env', \
         '\"use strict\";return (async () => {{' + __js + '\\n}})();');\n\
         Promise.resolve(__run(globalThis.input, globalThis.ferrite, globalThis.console, globalThis.fetch, globalThis.env))\n\
         .then((v) => {{ ferrite._output(v); std.exit(0); }},\n\
               (e) => {{ const m = (e && e.message !== undefined) ? String(e.message) : String(e); \
                         const st = (e && e.stack) ? ('\\n' + e.stack) : ''; \
                         std.err.puts('UNCAUGHT: ' + m + st + '\\n'); \
                         ferrite._output(undefined); std.exit(3); }});"
    )
}

/// Minimal JSON string encoder for embedding source safely (no serde dep needed
/// here; the snippet text can contain anything).
fn json_string(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}
